CREATE PROCEDURE [CDN].[POS_ZapiszHist]
	@pckid int,
	@guid nvarchar(40),
	@Numer int
AS
BEGIN
SET NOCOUNT OFF;	
	INSERT into cdn.PicoLog([PcL_PcKID], [PcL_ObiTyp], [PcL_ObiNumer], [PcL_TStamp],[PcL_ObiektID],[PcL_ObiektGUID])
	select distinct @pckid,32,isnull((select max(pl.PcL_ObiNumer)+1 from cdn.PicoLog pl where pl.PcL_ObiTyp=32 and pl.pcl_pckid=@pckid),0),DATEDIFF(second, convert(datetime,'01-01-1990',105),convert(datetime, getdate(), 105)),Knt_GIDNumer,@guid
 	from cdn.KntKarty WHERE Knt_GIDNumer = @Numer and not exists(select * from cdn.picolog where PcL_ObiektGUID = @guid and PcL_PcKID = @pckid)
END
